INSERT INTO purpose VALUES('core-sequent','boundary::ConsumerArity','struct','Names the number of children a consumer frame takes, so the check and the machine read the count rather than a constant.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','boundary::NodeCount','struct','Names a count of arena nodes, so a size or a length reads as a count and not an address.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','boundary::ProducerArity','struct','Names the number of children a producer head declares, so the check and the machine read the count rather than a constant.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','bridge::ConstructorResolver','struct','Maps the cell substrate''s constructor symbols to the IL''s constructor tags, so a reification resolves a symbol to its head.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','bridge::ReifyRefusal','enum','Names why a command pattern has no reification: a metavariable, an unresolved symbol, an arity mismatch or an operation frame.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','bridge::reify_command','function','Reifies a ground command pattern into the command IL, lowering constructor applications to producers and return frames to their binders.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','check::ArityHead','enum','Names the head whose arity a node is held to, so the check reads the declared count rather than a constant.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','check::CheckRefusal','enum','Names why a command is not well formed: a dangling reference, an arity mismatch, a focus break, a polarity mismatch, a closure naming an outer covariable or a closure whose code is no closure former.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','check::FreeSet','struct','Holds the free variables and covariables of a well-formed command, counted from the command itself.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','check::annotations::Annotated','struct','Holds the counts of the check of the annotations: the fields and the binders it verifies, and those it cannot verify.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','check::annotations::check_annotations','function','Checks the type of each field of the IL against the type of the binder of its variable, by id, refusing a disagreement by name and counting what it verifies.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','check::check_command','function','Checks a command and every node below it for reference integrity, arity, focus, polarity and second-class closures, answering the command''s free set.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','closure::ClosureRefusal','enum','Names why a closure rewrite is refused: a dangling node, a producer that is no closure, an annotation naming a moved variable, an index past its width or a mint the arena refuses.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','closure::beta','function','Enters one closure cut against a frame its code answers, binding the environment and the frame''s arguments over the arm''s body.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','closure::convert','function','Converts one closure to its normal form, moving every intuitionistic context variable its code names into its environment.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','closure::convert_all','function','Converts every closure under a root, inner ones first, so a program''s closures name nothing past their environments.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','closure::convert_step','function','Moves the greatest intuitionistic context variable a closure''s code names into its environment, the conversion rule applied once.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','closure::enter_all','function','Enters every closure cut under a root against the frame its code answers.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','definitions::Definition','enum','Names what a constant stands for when a run meets it: a focused value to evaluate, or an opaque declaration to carry.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','definitions::Definitions','struct','Holds the definitions a run unfolds, by admission position, so a run looks up a constant''s body where it first meets it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','focus::FocusOrigin','enum','Names the source construct a focused command was created for, the un-sugaring view of a focused term.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','focus::FocusRefusal','enum','Names why a translation was refused: a dangling core id, a static code, a hole, or a refused mint.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','focus::Provenance','struct','Records the origin of every command focusing created, in creation order, so a focused term reads back its source constructs.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','focus::Recorded','enum','Names what a checker''s record holds under one key: one type, or a conflict of two.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','focus::Typed','struct','Holds the value types a caller''s checker gives the binders of binds and the fields of constructors, and the signatures of the declared families, for focusing to import.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','focus::Unknown','enum','Names why focusing gave a position the unknown type: an open variable, no checker, a miss, a conflict, a parameter of its family or a field focusing makes itself.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','focus::Unknowns','struct','Counts the positions focusing gave the unknown type, by cause.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','focus::Writers','struct','Holds the bind writers a caller''s checker types as returners with the closed empty row, which focus focuses apart from their binders and marks independent.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','focus::focus_computation','function','Focuses a core computation against the terminal continuation, translating it into a command and recording each created command''s origin.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','focus::focus_definition','function','Focuses a declaration''s body into the producer its constant unfolds to, a value or the capture that runs a computed value once.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','focus::focus_top_value','function','Focuses a declaration''s value against the terminal consumer, the cut of its producer against the top.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','focus::focus_value','function','Focuses a core value into a producer, translating its constructors and thunks into the IL''s producer nodes.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','identity::MotiveHead','enum','Names the head of a transport motive''s part that no transport row reads, what a refused element transport names.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::CELL','constant','Names the interface a scheduled cut performs to spawn its writer and to read it, spelled so that no source claims it and the run offers both to its host.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::Captures','struct','Holds the intuitionistic bindings a suspension captures where it is created, as de Bruijn indices counted there.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::CommandArena','struct','Holds every IL node of one translation or run, append-only, with each node''s scope beside it, the binders marked independent and a watermark for rollback.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::CommandId','struct','Names the address of a command node in the arena, so a cut or a frame points at it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::CommandNode','enum','Names one command node: a cut, an operation request, a handler, a resumption, a delimited context, or a memory form.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::ConstructorTag','enum','Names a constructor head of a positive type: a tuple, a record, a list, an injection, a lift, or a nominal datatype''s constructors.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::ConsumerId','struct','Names the address of a consumer node in the arena, so a cut or a frame points at it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::ConsumerNode','enum','Names one consumer node: a covariable, a value binder, a destructor frame, a match, a selection, a fold, or the terminal consumer.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::CopatternArm','struct','Holds one arm of a copattern object: the destructor head it answers and the command run when a frame of that head arrives.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::CovariableIndex','struct','Names a bound covariable as a de Bruijn index counting covariable binders outward, so a frame argument reads its binder.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::DestructorTag','enum','Names a destructor head: an observation a consumer frame makes, application, forcing, or projection.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::Independence','enum','Names whether a run may start a binder''s writer before the binder''s body: a writer that performs no operation reorders no effect.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::Introduces','enum','Names what a handler binds besides the subject''s return covariable: nothing, or a capability the subject exercises.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::MarkRefusal','enum','Names why the arena refused to mark a binder independent: a dangling consumer, or a consumer that is not a binder.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::MintRefusal','enum','Names why the arena refused to mint a node: a dangling child, an unresolvable annotation, or a full family.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::NodeAddress','enum','Names the address of a node of any of the three families, so a walk or a refusal names a node without its family.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::NodeFamily','enum','Names the three node families of the arena: producer, consumer, command.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::NodeScope','struct','Holds a node''s free indices, read off its carried support, so the check reads scope rather than rebuilding it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::Opens','struct','Holds the binders a node opens over one of its children, producer binders per zone and covariable binders, as the child visitors report them.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::PatternArm','struct','Holds one arm of a pattern match: the constructor head it answers and the command run when a value of that head arrives.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::ProducerId','struct','Names the address of a producer node in the arena, so a cut or a frame points at it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::ProducerNode','enum','Names one producer node: a value, a constructor, a thunk, a recursive thunk, a copattern object, an abstract closure, or a context capture.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::REACHED','constant','Names the one operation of the reached hole, so a request for it is offered to the host.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::REACHED_HOLE','constant','Names the interface a reached hole performs, so no source can claim it and the request reaches the host.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::READ','constant','Names the cell operation whose payload is the handle a spawn replied with and whose reply is that writer''s answer.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::Route','enum','Names how an operation request finds the handler that answers it: the nearest delimiter, or the capability that introduced it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::SPAWN','constant','Names the cell operation whose payload is a writer''s thunk and whose reply is a handle a read names.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::Selector','enum','Names the field a select node reads from the value it meets: a tuple''s component or a record''s label.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::SequentWatermark','struct','Holds a snapshot of the three family lengths and the scopes'' word arena, so restoring an arena drops exactly the nodes minted after it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::Suspension','enum','Names a suspended command a run closes over the bindings it captures: a thunk, a recursive thunk, a copattern object, or a bind frame.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::command_annotations','function','Lists the core types that a command names: the types of an operation''s or a handler''s interface, and the protocol of a fork.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::command_children','function','Visits a command''s children in edge order, each beside the binders the command opens over it, stopping at the first refusal.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::consumer_annotations','function','Lists the core types that a consumer names: the element type and the result type of a fold, and the type a binder binds.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::consumer_children','function','Visits a consumer''s children in edge order, each beside the binders the consumer opens over it, stopping at the first refusal.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::producer_annotations','function','Lists the core types that a producer names: the type of each producer field of a constructor.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','il::producer_children','function','Visits a producer''s children in edge order, each beside the binders the producer opens over it, stopping at the first refusal.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','inspect::Stats','struct','Holds the node population of an arena: the counts of its three families.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','inspect::dump','function','Writes a textual dump of a focused root: its rendering, its origin and the arena''s population.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','inspect::origin_histogram','function','Counts how many commands each core former contributed, the un-sugaring view of a focused term.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','inspect::stats','function','Counts an arena''s three node families, the population view of a focused term.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','outcome::Outcome','enum','Names how a run of a focused command ended: a value returned to the empty frame, or a named reason it stopped short.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','outcome::Stuck','enum','Names why a run stopped short of a value: no handler, no reset, a refused primitive, an undefined constant, or an unmatched scrutinee.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','ownership::Entry','struct','Holds one node''s reading: the names it duplicates before it runs, the names dropped on entry, and the captures a kept body duplicates.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','ownership::Ownership','struct','Holds where every node reachable from a set of roots duplicates, drops and reuses, read off the carried supports one node at a time.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','ownership::OwnershipRefusal','enum','Names why a reading was refused: a root or a child the arena does not hold.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','ownership::Reuse','struct','Pairs a match whose scrutinee dies in a branch with a constructor of the scrutinee''s size that the branch builds in its window.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','ownership::Runs','enum','Names how often a suspension''s body may run: at most once, or any number of times.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','ownership::reach','function','Walks the nodes reachable from a set of roots, appending each to the order and the seen set once, in first-visit order.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','pretty::render_command','function','Renders a command as text in the IL''s notation, depth-bounded, with a dangling address rendered as a marker.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','pretty::render_consumer','function','Renders a consumer as text in the IL''s notation, depth-bounded, with a dangling address rendered as a marker.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','pretty::render_producer','function','Renders a producer as text in the IL''s notation, depth-bounded, with a dangling address rendered as a marker.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','readback::ReadbackRefusal','enum','Names why a heap value has no core reading: an unreadable value, a dangling address, a decoding refusal, or a mismatched environment.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','readback::read_back_terminal','function','Reads a run''s terminal back as a core computation: a return of a positive value, or the function a copattern object denotes.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','readback::read_back_value','function','Reads a positive heap value back as a core value, closing a thunk or a function over its environment''s readbacks.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','spawn::ScheduleRefusal','enum','Names why a command has no schedule: a rewrite the closure conversion refused, or the cell interface refused as a signature.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','spawn::spawn_independent','function','Rewrites each cut whose binder is marked independent to spawn its writer and to read it before the binder is first needed, in the root and in each definition.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','spawn::spawn_independent_definitions','function','Rewrites each marked cut of the definitions alone, so a program schedules its definitions once for every root it runs.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','store::Accumulation','enum','Names the observation that grew an accumulator from the one it holds: a force, or an application to the argument it holds.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','store::ClosedCommand','struct','Holds a bind frame''s command and the environment it runs under, so a literal stack''s frame is a closed command.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','store::CopyRefusal','enum','Names why a value did not copy into another store: a dangling address or chain, a capability whose address is its identity, or the destination''s refusal.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','store::Environment','struct','Holds the innermost producer binding of a persistent chain, so extending one never copies it and a closure captures one by value.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','store::HeapFamily','enum','Names the families of the store, so a full-family refusal names the family that reached its ceiling.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','store::HeapValue','enum','Holds a value a run answered with or named: a literal, a constructed value, an opaque constant, a suspended command closed over its environment, or an accumulator standing for a free variable and the observations of it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','store::HeapValueId','struct','Names the address of a heap value in the store, so sharing a value is sharing its address.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','store::Store','struct','Holds the values a run moved out and the environments they close over, an append-only heap over persistent environment chains.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','store::StoreFault','enum','Names why the store refused an operation: a full family, or a value that names a later one.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','unfocus::UnfocusRefusal','enum','Names why a command or producer has no core reading: a dangling address, a node outside the focused image, or an escaping continuation.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','unfocus::unfocus_command','function','Decodes a command as the core computation it focuses, the left inverse of focusing, with the terminal consumer as its return point.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-sequent','unfocus::unfocus_value','function','Decodes a producer as the core value it focuses, the left inverse of focusing a value.',NULL,'fits','sound',NULL);
